INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM209MA1K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A carpenter can install $23$ floor tiles in $2$ hours. At this rate, how many floor tiles can the carpenter install in $7$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$46$"},{"key":"B","text":"$80.5$"},{"key":"C","text":"$161$"},{"key":"D","text":"$69$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{23}{2} = 11.5$ tiles per hour. In $7$ hours, the carpenter installs $11.5 \\times 7 = 80.5$ tiles. The distractor $46$ results from simply doubling the $2$-hour count without scaling to $7$ hours. The distractor $161$ results from multiplying $23 \\times 7$ without accounting for the $2$-hour base period. The distractor $69$ results from multiplying $23 \\times 3$, treating the difference $7 - 2 = 5$ incorrectly as a multiplier of $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20P46C0', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $7x + 3y = 63$ ?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$9$"},{"key":"C","text":"$21$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting $y = 0$ into $7x + 3(0) = 63$ gives $7x = 63$, so $x = 9$. The value $21$ results from setting $x = 0$ instead, which gives the $y$-intercept ($3y = 63$, $y = 21$) rather than the $x$-intercept. The value $63$ results from setting $y = 0$ to get $7x = 63$ but reporting $63$ instead of dividing by $7$. The value $3$ results from first correctly finding $x = 9$ and then erroneously dividing by $3$ (the coefficient of $y$), or equivalently computing $63 \\div 21 = 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20UDJZ1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducts a study to test a new migraine medication. The company recruits 300 volunteers who experience frequent migraines and randomly assigns them to receive either the new medication or a placebo. Neither the participants nor the doctors evaluating outcomes know which treatment each participant received. After 12 weeks, participants taking the new medication reported $37\\%$ fewer migraines than those taking the placebo. A journalist writes: "This medication eliminates migraines in $37\\%$ of patients." Which of the following best identifies the error in the journalist''s statement?', NULL, $lyceon_json$[{"key":"A","text":"The journalist incorrectly describes a $37\\%$ reduction in migraine frequency as elimination of migraines in $37\\%$ of patients."},{"key":"B","text":"The study used random assignment, so it cannot support any claim about the medication's effect."},{"key":"C","text":"Because a placebo was used, the observed reduction may be entirely due to the placebo effect rather than the medication."},{"key":"D","text":"A sample of 300 volunteers is too small to draw meaningful conclusions about the medication."}]$lyceon_json$::jsonb, 'A', NULL, E'The study found a $37\\%$ reduction in migraine frequency — meaning participants experienced $37\\%$ fewer migraines, not that $37\\%$ of participants had their migraines completely eliminated. The journalist conflated a percentage decrease in frequency with a percentage of patients cured, which are fundamentally different claims. The assertion that random assignment prevents causal claims is backwards: random assignment is precisely what enables causal inference. The suggestion that the placebo effect accounts for the entire reduction ignores that the double-blind, placebo-controlled design exists to isolate the medication''s effect beyond the placebo response — the $37\\%$ figure already represents the difference between medication and placebo groups. The concern about sample size is not the primary error in the journalist''s statement; 300 participants is a reasonable sample for a clinical trial.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20W4N05', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A store sells pens for $\\$7$ each. Dario has $\\$52$ and must save at least $\\$11$ for a taxi ride home. What is the maximum number of pens Dario can buy?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dario can spend at most $52 - 11 = 41$ dollars on pens, so the inequality is $7n \\leq 41$, giving $n \\leq \\frac{41}{7} \\approx 5.857$. Since $n$ must be a whole number, the maximum is $5$. The distractor $4$ arises from incorrectly concluding that $n$ must be strictly less than $5$ and rounding down an extra unit. The distractor $6$ comes from rounding $5.857$ up to $6$ rather than taking the greatest integer less than or equal to $5.857$. The distractor $7$ results from ignoring the taxi constraint entirely and computing $\\lfloor 52/7 \\rfloor = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21ZRAQX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $h$ satisfies $h(5) = 23$ and $h(11) = 59$. What is the value of $h(0)$ ?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$6$"},{"key":"C","text":"$17$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{59 - 23}{11 - 5} = \\frac{36}{6} = 6$. Using $h(x) = 6x + b$ and $h(5) = 23$: $30 + b = 23$, so $b = -7$. Therefore $h(0) = -7$. The value $6$ results from finding the slope but reporting it as $h(0)$ instead of computing the $y$-intercept. The value $17$ results from subtracting only one slope step from $h(5)$, computing $23 - 6 = 17$, rather than subtracting five slope steps to reach $h(0) = 23 - 5(6) = -7$. The value $29$ results from moving in the wrong direction, adding a slope step to $h(5)$ instead of subtracting: $23 + 6 = 29$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM235HFEX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A veterinary clinic recorded information about 79 animals seen last week. Of the 37 dogs, 23 were vaccinated and 14 were not vaccinated. Of the 30 cats, 19 were vaccinated and 11 were not vaccinated. Of the 12 birds, 8 were vaccinated and 4 were not vaccinated. If one of the dogs is selected at random, what is the probability that it was vaccinated?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{79}$"},{"key":"B","text":"$\\frac{23}{50}$"},{"key":"C","text":"$\\frac{23}{37}$"},{"key":"D","text":"$\\frac{14}{37}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since the selection is restricted to dogs, the sample space is the 37 dogs. Of those, 23 were vaccinated, so the conditional probability is $\\frac{23}{37}$. The value $\\frac{23}{79}$ incorrectly uses all 79 animals as the denominator instead of restricting to dogs. The value $\\frac{23}{50}$ incorrectly uses the total number of vaccinated animals (50) as the denominator, computing $P(\\text{dog} \\mid \\text{vaccinated})$ rather than $P(\\text{vaccinated} \\mid \\text{dog})$. The value $\\frac{14}{37}$ gives the probability that a randomly selected dog was not vaccinated, reversing the intended outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26XL9D8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'What is the radius of the circle with equation $(x - 7)^2 + (y + 3)^2 = 64$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$32$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $r$ is the radius. Here $r^2 = 64$, so $r = \\sqrt{64} = 8$. The value $64$ results from reading $r^2$ as $r$ without taking the square root. The value $32$ results from dividing $64$ by $2$ instead of taking its square root. The value $4$ results from an error such as computing $\\sqrt{64} = 8$ and then halving it, perhaps confusing radius with diameter in reverse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26Z4LNF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle has equation $x^2 + y^2 - 2x + 6y - 159 = 0$. A chord of this circle has its midpoint at $(6, -3)$. What is the length of the chord?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24', ARRAY['24'], E'First, rewrite the equation in standard form by completing the square: $(x^2 - 2x + 1) + (y^2 + 6y + 9) = 159 + 1 + 9 = 169$, so $(x - 1)^2 + (y + 3)^2 = 169$. The center is $(1, -3)$ and the radius is $13$. The distance from the center $(1, -3)$ to the chord midpoint $(6, -3)$ is $\\sqrt{(6-1)^2 + (-3-(-3))^2} = \\sqrt{25} = 5$. By the perpendicular-from-center-to-chord property, the half-chord length is $\\sqrt{r^2 - d^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore the full chord length is $2 \\times 12 = 24$. Common errors include forgetting to double the half-chord (giving $12$) or making an error in completing the square that leads to an incorrect radius.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27ZOXR7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'For what value of $k$ does the equation $$k(2x + 5) - 3(4x - 1) = 2x + 9$$ have no solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Expanding the left side gives $2kx + 5k - 12x + 3$, which can be rewritten as $(2k - 12)x + (5k + 3)$. The equation becomes $(2k - 12)x + 5k + 3 = 2x + 9$. For the equation to have no solution, the coefficients of $x$ must be equal on both sides while the constant terms differ. Setting the coefficients equal: $2k - 12 = 2$, so $2k = 14$ and $k = 7$. Checking the constants when $k = 7$: the left side constant is $5(7) + 3 = 38$, while the right side constant is $9$. Since $38 \\neq 9$, the equation $2x + 38 = 2x + 9$ is a contradiction, confirming no solution exists when $k = 7$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM285E6JR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $$\\frac{5(2x + 9)}{3} = 45$$ ?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by $3$ gives $5(2x + 9) = 135$. Dividing both sides by $5$ gives $2x + 9 = 27$. Subtracting $9$ from both sides gives $2x = 18$, and dividing by $2$ gives $x = 9$. The value $18$ results from correctly reaching $2x = 18$ but stopping before dividing by $2$. The value $0$ results from omitting the multiplication by $3$, which leads to $5(2x + 9) = 45$, then $2x + 9 = 9$, then $2x = 0$, so $x = 0$. The value $3$ results from reaching $2x + 9 = 27$ and then dividing $27$ by $9$ instead of subtracting $9$ from $27$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28AVWF6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A parking garage charges different daily rates for cars and trucks. On Monday, $7$ cars and $3$ trucks paid a combined total of $\\$89$. On Tuesday, $4$ cars and $9$ trucks paid a combined total of $\\$131$. What is the daily parking cost, in dollars, for one truck?', NULL, $lyceon_json$[{"key":"A","text":"$\\$8$"},{"key":"B","text":"$\\$9$"},{"key":"C","text":"$\\$11$"},{"key":"D","text":"$\\$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $c$ be the car rate and $t$ be the truck rate. The system is $7c + 3t = 89$ and $4c + 9t = 131$. Multiplying the first equation by $3$ gives $21c + 9t = 267$. Subtracting the second equation: $(21c + 9t) - (4c + 9t) = 267 - 131$, yielding $17c = 136$ and $c = 8$. Substituting into the first equation: $56 + 3t = 89$, so $3t = 33$ and $t = 11$. The distractor $\\$8$ is the car rate, not the truck rate — a misread of what the question asks. The distractor $\\$9$ results from an arithmetic error when subtracting $56$ from $89$: computing $89 - 56 = 27$ instead of $33$, then $27/3 = 9$. The distractor $\\$13$ arises from correctly finding $c = 8$ but making a subtraction error in the second equation: computing $131 - 32 = 117$ instead of $99$, then $117/9 = 13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28FCPGT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A parking garage contains 13 sedans, 9 SUVs, and 5 trucks. If one vehicle is selected at random, what is the probability that the selected vehicle is an SUV?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{27}$"},{"key":"B","text":"$\\frac{1}{3}$"},{"key":"C","text":"$\\frac{9}{22}$"},{"key":"D","text":"$\\frac{13}{27}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of vehicles is $13 + 9 + 5 = 27$. The probability of selecting an SUV is $\\frac{9}{27} = \\frac{1}{3}$. The value $\\frac{5}{27}$ results from using the number of trucks instead of SUVs. The value $\\frac{9}{22}$ results from dividing the number of SUVs by the number of non-SUV vehicles ($13 + 9 = 22$) rather than by the total. The value $\\frac{13}{27}$ results from using the number of sedans instead of SUVs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M4VFN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $(3x + 7)^\\circ$ and the measure of angle $Q$ is $(2x + 11)^\\circ$. If the exterior angle at vertex $R$ measures $123^\\circ$, what is the measure of angle $P$, in degrees?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$53$"},{"key":"C","text":"$57$"},{"key":"D","text":"$70$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the exterior angle theorem, the exterior angle at a vertex equals the sum of the two non-adjacent interior angles. So $(3x + 7) + (2x + 11) = 123$, which simplifies to $5x + 18 = 123$, giving $x = 21$. Substituting back, angle $P = 3(21) + 7 = 70^\\circ$. The value $21$ comes from stopping at $x = 21$ without substituting back into the expression for angle $P$. The value $53$ comes from computing angle $Q = 2(21) + 11 = 53$ instead of angle $P$. The value $57$ comes from computing the interior angle at $R$ as $180 - 123 = 57$ rather than the requested angle $P$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A0QZD2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the population $P$ of a bacteria colony after $t$ hours using the equation $P = 260 \\cdot (1.37)^t$. Another colony is modeled by $P = 410 \\cdot (1.19)^t$. After how many complete hours will the first colony''s population first exceed that of the second colony?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'We need $260 \\cdot (1.37)^t > 410 \\cdot (1.19)^t$. Testing values: at $t = 3$, colony 1 has $260 \\times 1.37^3 \\approx 260 \\times 2.5726 \\approx 668.9$ and colony 2 has $410 \\times 1.19^3 \\approx 410 \\times 1.6852 \\approx 690.9$, so colony 1 is still smaller. At $t = 4$, colony 1 has $260 \\times 1.37^4 \\approx 260 \\times 3.5245 \\approx 916.4$ and colony 2 has $410 \\times 1.19^4 \\approx 410 \\times 2.0054 \\approx 822.2$, so colony 1 first exceeds colony 2 at $t = 4$. The distractor $3$ results from rounding errors in computing powers. The distractor $5$ results from an arithmetic miscalculation of the growth factors. The distractor $6$ results from misreading the question as asking when colony 1 is double colony 2.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A3CWJ9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $6x^2 = 726$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Divide both sides by $6$ to get $x^2 = 121$. Taking the positive square root of both sides gives $x = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIY6HF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling firm surveys 800 randomly selected voters and reports that $41\\% \\pm 2.7\\%$ plan to vote for Measure J. A rival firm surveys 200 randomly selected voters from the same population and reports $46\\% \\pm 5.1\\%$ for the same measure. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The true percentage must be closer to $41\\%$ than to $46\\%$ because the first survey has a smaller margin of error."},{"key":"B","text":"The two surveys provide contradictory evidence about voter support for Measure J."},{"key":"C","text":"The confidence intervals from the two surveys overlap, so the results are consistent with each other."},{"key":"D","text":"Because the surveys report different percentages, at least one of the polling firms made a sampling error."}]$lyceon_json$::jsonb, 'C', NULL, E'The first survey''s confidence interval is $41\\% - 2.7\\% = 38.3\\%$ to $41\\% + 2.7\\% = 43.7\\%$. The second survey''s confidence interval is $46\\% - 5.1\\% = 40.9\\%$ to $46\\% + 5.1\\% = 51.1\\%$. These intervals overlap in the range $40.9\\%$ to $43.7\\%$, so both surveys are consistent with a true value in that overlapping region. The claim that the true value must be closer to $41\\%$ confuses precision with accuracy — a smaller margin of error does not guarantee the sample statistic is closer to the true value. The claim that the surveys are contradictory is incorrect because overlapping confidence intervals indicate compatibility. The claim that a sampling error occurred misunderstands that different random samples from the same population naturally yield different statistics.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AK2MTM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A scientist models the number of cells in a culture using the function $P(t) = 150 \\cdot 4^{t/6}$, where $t$ is the number of hours after the initial observation. According to this model, by what factor does the number of cells increase every $9$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'C', NULL, E'The growth factor over any $9$-hour interval is $\\frac{P(t + 9)}{P(t)} = \\frac{150 \\cdot 4^{(t+9)/6}}{150 \\cdot 4^{t/6}} = 4^{9/6} = 4^{3/2}$. Evaluating $4^{3/2} = (\\sqrt{4})^3 = 2^3 = 8$. The distractor $4$ results from using only the base of the exponential without accounting for the fractional exponent, equivalent to computing the factor for a $6$-hour interval ($4^1 = 4$) instead of a $9$-hour interval. The distractor $6$ results from multiplying the base by the exponent ($4 \\times \\frac{3}{2} = 6$) instead of raising the base to the exponent. The distractor $16$ results from rounding the exponent $\\frac{3}{2}$ up to $2$ and computing $4^2 = 16$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAWQPZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a novel for $\\$45$. During a sale, the price is reduced by $16\\%$. What is the sale price of the novel?', NULL, $lyceon_json$[{"key":"A","text":"$\\$29.00$"},{"key":"B","text":"$\\$37.80$"},{"key":"C","text":"$\\$38.40$"},{"key":"D","text":"$\\$52.20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $45 \\times 0.16 = 7.20$. The sale price is $45 - 7.20 = 37.80$. The distractor $\\$29.00$ comes from subtracting $16$ from $45$ instead of computing $16\\%$ of $45$. The distractor $\\$38.40$ comes from computing $45 \\times 0.84$ incorrectly as $38.40$ due to a multiplication error. The distractor $\\$52.20$ comes from adding the $16\\%$ to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DCLE6C', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{10x^3 - 23x^2 + 13x - 2}{2x - 1} = ax^2 + bx + c$ for all values of $x$ where $x \\neq \\frac{1}{2}$, what is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'Perform polynomial long division of $10x^3 - 23x^2 + 13x - 2$ by $2x - 1$. Dividing $10x^3$ by $2x$ gives $5x^2$. Multiplying $5x^2(2x - 1) = 10x^3 - 5x^2$ and subtracting yields $-18x^2 + 13x - 2$. Dividing $-18x^2$ by $2x$ gives $-9x$. Multiplying $-9x(2x - 1) = -18x^2 + 9x$ and subtracting yields $4x - 2$. Dividing $4x$ by $2x$ gives $2$. Multiplying $2(2x - 1) = 4x - 2$ and subtracting yields $0$. So the quotient is $5x^2 - 9x + 2$, meaning $a = 5$, $b = -9$, and $c = 2$. Therefore $a + b + c = 5 + (-9) + 2 = -2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DG7NI7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are the solutions to $2x^2 + 9x - 35 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -\\frac{5}{2}$ and $x = 7$"},{"key":"B","text":"$x = \\frac{5}{2}$ and $x = -7$"},{"key":"C","text":"$x = 5$ and $x = -7$"},{"key":"D","text":"$x = \\frac{5}{2}$ and $x = -\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor $2x^2 + 9x - 35$ by finding two numbers whose product is $2 \\times (-35) = -70$ and whose sum is $9$: those are $14$ and $-5$. Rewriting: $2x^2 + 14x - 5x - 35 = 2x(x + 7) - 5(x + 7) = (2x - 5)(x + 7) = 0$. Setting each factor to zero gives $x = \\frac{5}{2}$ and $x = -7$. The distractor $x = -\\frac{5}{2}$ and $x = 7$ results from a sign error when solving each factor (reversing both signs). The distractor $x = 5$ and $x = -7$ arises from solving $2x - 5 = 0$ as $x = 5$ instead of $x = \\frac{5}{2}$, neglecting to divide by the leading coefficient $2$. The distractor $x = \\frac{5}{2}$ and $x = -\\frac{7}{2}$ results from incorrectly dividing both solutions by the leading coefficient $2$, turning $x = -7$ into $x = -\\frac{7}{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E7RXIM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 9x + 7$, what is the value of $f(6)$ ?', NULL, $lyceon_json$[{"key":"A","text":"$42$"},{"key":"B","text":"$47$"},{"key":"C","text":"$54$"},{"key":"D","text":"$61$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 6$ gives $f(6) = 9(6) + 7 = 54 + 7 = 61$. The value $54$ results from computing $9 \\times 6 = 54$ but forgetting to add $7$. The value $47$ results from subtracting $7$ instead of adding it: $54 - 7 = 47$. The value $42$ results from multiplying $6$ by $7$ (the constant term) instead of by $9$ (the coefficient of $x$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EE0ZO9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A teacher records quiz scores for $5$ students: $67$, $73$, $81$, $81$, $88$. What is the median score?', NULL, $lyceon_json$[{"key":"A","text":"$73$"},{"key":"B","text":"$77$"},{"key":"C","text":"$78$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'D', NULL, E'The scores in order are $67, 73, 81, 81, 88$. With $5$ values, the median is the $3$rd value, which is $81$. The distractor $73$ results from selecting the $2$nd value instead of the $3$rd. The distractor $77$ results from averaging $73$ and $81$ as if finding the median of an even number of values. The distractor $78$ results from computing the mean $(67 + 73 + 81 + 81 + 88) \\div 5 = 78$ and confusing it with the median.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EKCWTL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $30^\\circ$. If the hypotenuse has length $22$, what is the length of the side opposite the $30^\\circ$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$11\\sqrt{2}$"},{"key":"C","text":"$11\\sqrt{3}$"},{"key":"D","text":"$22\\sqrt{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In a $30$-$60$-$90$ triangle, the side opposite the $30^\\circ$ angle is half the hypotenuse. Therefore the side opposite $30^\\circ$ is $\\frac{22}{2} = 11$. The value $11\\sqrt{3}$ results from computing the side opposite the $60^\\circ$ angle instead of the $30^\\circ$ angle. The value $11\\sqrt{2}$ results from incorrectly applying the $45$-$45$-$90$ ratio to a $30$-$60$-$90$ triangle. The value $22\\sqrt{3}$ results from multiplying the hypotenuse by $\\sqrt{3}$ instead of dividing by $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FQ2B2N', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'In the system of equations below, what is the value of $y$?$$\\begin{cases} 2x + y = 17 \\\\ x = 3 \\end{cases}$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Substituting $x = 3$ into the first equation gives $2(3) + y = 17$, which simplifies to $6 + y = 17$. Subtracting $6$ from both sides yields $y = 11$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GNVJUG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following represents all values of $x$ that satisfy $8x + 16 \\leq 56$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 5$"},{"key":"B","text":"$x \\geq 5$"},{"key":"C","text":"$x \\leq 9$"},{"key":"D","text":"$x \\geq 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $16$ from both sides gives $8x \\leq 40$. Dividing both sides by $8$ yields $x \\leq 5$. The distractor $x \\geq 5$ results from flipping the inequality direction without cause. The distractor $x \\leq 9$ comes from adding $16$ to $56$ instead of subtracting, producing $8x \\leq 72$ and $x \\leq 9$. The distractor $x \\geq 9$ combines both errors: adding $16$ and flipping the inequality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HAQHOL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, the measure of angle $A$ is $52^\\circ$ and the measure of angle $B$ is $71^\\circ$. Point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. What is the measure, in degrees, of angle $ADC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '97', ARRAY['97'], E'First, the measure of angle $C = 180 - 52 - 71 = 57^\\circ$. Since $\\overline{AD}$ bisects angle $A$, the measure of angle $DAC = \\frac{52}{2} = 26^\\circ$. In triangle $ADC$, the sum of the interior angles is $180^\\circ$, so the measure of angle $ADC = 180 - 26 - 57 = 97^\\circ$. A common error is to use the full angle $A$ instead of the bisected half, which would give $180 - 52 - 57 = 71^\\circ$. Another error is to forget to find angle $C$ first and instead attempt to use only the bisected angle with angle $B$, yielding $180 - 26 - 71 = 83^\\circ$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HFAZ1N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A store marks up a wholesale item by $35\\%$ and then offers a $20\\%$ discount on the marked-up price. If the final selling price is $\\$43.20$, what was the original wholesale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Let the wholesale price be $w$. The marked-up price is $1.35w$. After a $20\\%$ discount, the selling price is $1.35w \\times 0.80 = 1.08w$. Setting $1.08w = 43.20$ gives $w = \\frac{43.20}{1.08} = 40$. The wholesale price is $\\$40$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTP2QW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A set of $11$ positive integers has a median of $19$ and a mean of $23$. The largest value in the set is replaced by a value that is $30$ greater. Which of the following must be true about the new set?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases by $\\frac{30}{11}$ and the median remains $19$."},{"key":"B","text":"The mean increases by $30$ and the median remains $19$."},{"key":"C","text":"The mean increases by $\\frac{30}{11}$ and the median increases."},{"key":"D","text":"The mean and the median both remain unchanged."}]$lyceon_json$::jsonb, 'A', NULL, E'The original sum is $11 \\times 23 = 253$. Replacing the largest value with one that is $30$ greater increases the sum by $30$, making the new mean $\\frac{253 + 30}{11} = \\frac{283}{11} \\approx 25.73$, an increase of $\\frac{30}{11}$. The median is the $6$th value when sorted. Since only the largest value changed (it was already the largest and became even larger), the $6$th value remains $19$. The distractor stating the mean increases by $30$ confuses total change with per-element change. The distractor claiming the median increases incorrectly assumes changing an extreme value affects the middle. The distractor claiming both remain unchanged ignores the effect on the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I8KLTP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'The lines $x + 2y = 7$ and $3x - y = 7$ intersect at a single point. If the line $kx + 4y = 17$ also passes through this point of intersection, what is the value of $k$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'First, solve the system $x + 2y = 7$ and $3x - y = 7$. From the first equation, $x = 7 - 2y$. Substituting into the second equation: $3(7 - 2y) - y = 7$, which gives $21 - 6y - y = 7$, so $-7y = -14$ and $y = 2$. Then $x = 7 - 2(2) = 3$. The intersection point is $(3, 2)$. Substituting into $kx + 4y = 17$: $3k + 4(2) = 17$, so $3k + 8 = 17$, giving $3k = 9$ and $k = 3$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IF0OE0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'What are all values of $x$ that satisfy $\\frac{5x - 13}{4} \\geq \\frac{3x + 1}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq -15$"},{"key":"B","text":"$x \\geq -15$"},{"key":"C","text":"$x \\leq -11$"},{"key":"D","text":"$x \\geq 15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying both sides by $4$ gives $5x - 13 \\geq 2(3x + 1)$, which simplifies to $5x - 13 \\geq 6x + 2$. Subtracting $6x$ from both sides: $-x - 13 \\geq 2$. Adding $13$: $-x \\geq 15$. Dividing by $-1$ and flipping the inequality: $x \\leq -15$. The distractor $x \\geq -15$ results from correctly reaching $-x \\geq 15$ but forgetting to reverse the inequality when dividing by $-1$. The distractor $x \\leq -11$ comes from an arithmetic error when combining constants: computing $-13 + 2 = -11$ instead of correctly obtaining $2 + 13 = 15$ after rearranging terms. The distractor $x \\geq 15$ arises from treating $-x \\geq 15$ as $x \\geq 15$, ignoring the negative coefficient entirely rather than dividing by $-1$ and reversing the inequality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IU0C4I', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = 3x^2 - 42x + 151$ can be rewritten in the form $g(x) = 3(x - h)^2 + k$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-147$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$151$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square: $g(x) = 3(x^2 - 14x) + 151 = 3(x^2 - 14x + 49 - 49) + 151 = 3(x - 7)^2 - 147 + 151 = 3(x - 7)^2 + 4$. So $k = 4$. The distractor $-147$ results from computing $3 \\times (-49) = -147$ but failing to add back the original constant $151$, stopping the calculation prematurely. The distractor $7$ results from confusing $h$ with $k$, giving the $x$-coordinate of the vertex instead of the minimum value of the function. The distractor $151$ results from incorrectly assuming the constant term of the original expression equals $k$ without completing the square.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KD5PC6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of lengths $13$ inches and $19$ inches, and a height of $8$ inches. What is the area, in square inches, of the trapezoid?', NULL, $lyceon_json$[{"key":"A","text":"$104$"},{"key":"B","text":"$128$"},{"key":"C","text":"$152$"},{"key":"D","text":"$256$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a trapezoid is $\\frac{1}{2}(b_1 + b_2)(h) = \\frac{1}{2}(13 + 19)(8) = \\frac{1}{2}(32)(8) = 128$ square inches. The value $256$ results from computing $(13 + 19)(8) = 256$ and omitting the factor of $\\frac{1}{2}$. The value $152$ results from using only the longer base: $19 \\times 8 = 152$. The value $104$ results from using only the shorter base: $13 \\times 8 = 104$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KSKSS1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A company wants to test whether a new website layout increases the time customers spend browsing. The company randomly shows half of its visitors the new layout and the other half the original layout, then compares average browsing times between the two groups. Which of the following best describes this study design?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the company observed browsing behavior without intervening"},{"key":"B","text":"A randomized experiment, because visitors were randomly assigned to see one of two layouts"},{"key":"C","text":"A survey, because data was collected from website visitors"},{"key":"D","text":"A convenience sample, because only people who visited the website were included"}]$lyceon_json$::jsonb, 'B', NULL, E'The company randomly assigned visitors to one of two conditions (new layout or original layout) and compared outcomes, which is the defining feature of a randomized experiment. The description as an observational study is incorrect because the company actively assigned the treatment (layout) rather than merely recording naturally occurring behavior. Calling it a survey is incorrect because the company measured browsing time through recorded data, not through questionnaires. Describing it as a convenience sample confuses the sampling frame with the study design — while the study uses visitors who happened to come to the site, the random assignment of those visitors to treatments makes it an experiment, not a convenience sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LVOM5K', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $5(3x^2 - 2x + 7) - 4(x^2 - 6x + 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$11x^2 - 34x + 23$"},{"key":"B","text":"$11x^2 + 14x + 23$"},{"key":"C","text":"$11x^2 + 14x + 47$"},{"key":"D","text":"$19x^2 + 14x + 23$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $5(3x^2 - 2x + 7) = 15x^2 - 10x + 35$ and $-4(x^2 - 6x + 3) = -4x^2 + 24x - 12$. Combining like terms: $15x^2 - 4x^2 = 11x^2$, $-10x + 24x = 14x$, and $35 - 12 = 23$. The result is $11x^2 + 14x + 23$. The distractor $11x^2 - 34x + 23$ results from a sign error when distributing $-4$ to $-6x$, yielding $-10x - 24x = -34x$ instead of $-10x + 24x = 14x$. The distractor $11x^2 + 14x + 47$ comes from adding the constant terms $35 + 12 = 47$ instead of subtracting $35 - 12 = 23$. The distractor $19x^2 + 14x + 23$ comes from adding the leading coefficients $15 + 4 = 19$ instead of subtracting $15 - 4 = 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M5DVWG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a town, the population increased by $12\\%$ from 2020 to 2021 and then decreased by $15\\%$ from 2021 to 2022. If the population in 2022 was $11{,}424$, what was the population in 2020?', NULL, $lyceon_json$[{"key":"A","text":"$11{,}000$"},{"key":"B","text":"$12{,}000$"},{"key":"C","text":"$12{,}800$"},{"key":"D","text":"$13{,}440$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the 2020 population be $P$. After a $12\\%$ increase: $1.12P$. After a $15\\%$ decrease: $1.12P \\times 0.85 = 0.952P$. Setting $0.952P = 11{,}424$ gives $P = \\frac{11{,}424}{0.952} = 12{,}000$. The distractor $11{,}000$ comes from an approximate rounding error in the division. The distractor $12{,}800$ comes from dividing $11{,}424$ by $0.85$ only, reversing just the decrease and ignoring the increase. The distractor $13{,}440$ comes from dividing $11{,}424$ by $0.85 = 13{,}440$ and stopping there, treating the $12\\%$ increase as already accounted for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCPYQY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'Given the system of equations $$4x + 9y = 47$$ $$4x + 3y = 29$$ what is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Subtracting the second equation from the first eliminates $x$: $(4x + 9y) - (4x + 3y) = 47 - 29$, giving $6y = 18$ and $y = 3$. Substituting $y = 3$ into the second equation: $4x + 9 = 29$, so $4x = 20$ and $x = 5$. Therefore $x + y = 5 + 3 = 8$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O108QZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A warehouse stores 40 crates from Supplier X and 35 crates from Supplier Y. Of the crates from Supplier X, 6 contain at least one damaged item. Of the crates from Supplier Y, 7 contain at least one damaged item. If one crate is selected at random and is found to contain at least one damaged item, what is the probability that it came from Supplier Y?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{75}$"},{"key":"B","text":"$\\frac{1}{5}$"},{"key":"C","text":"$\\frac{6}{13}$"},{"key":"D","text":"$\\frac{7}{13}$"}]$lyceon_json$::jsonb, 'D', NULL, E'There are $6 + 7 = 13$ crates total that contain at least one damaged item. Of these 13 damaged crates, 7 came from Supplier Y. Therefore the probability is $\\frac{7}{13}$. The value $\\frac{7}{75}$ results from dividing by the total number of crates ($40 + 35 = 75$) rather than by the number of damaged crates, conflating $P(Y \\text{ and damaged})$ with $P(Y \\mid \\text{damaged})$. The value $\\frac{1}{5}$ equals $\\frac{7}{35}$, which is $P(\\text{damaged} \\mid Y)$ — the probability that a crate from Supplier Y is damaged — reversing the conditional. The value $\\frac{6}{13}$ uses the number of damaged crates from Supplier X instead of Supplier Y in the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P651I3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours spent studying and exam scores for $10$ students. The line of best fit has the equation $y = 6.5x + 52$, where $x$ is hours studied and $y$ is the predicted exam score. Based on this model, what is the predicted exam score for a student who studies for $4$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$74$"},{"key":"C","text":"$78$"},{"key":"D","text":"$82$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 4$ into $y = 6.5(4) + 52 = 26 + 52 = 78$. The distractor $72$ results from computing $6.5 \\times 4 = 26$ but adding to $46$ instead of $52$. The distractor $74$ results from using a slope of $5.5$ instead of $6.5$, giving $5.5 \\times 4 + 52 = 74$. The distractor $82$ results from misreading the intercept as $56$, giving $6.5 \\times 4 + 56 = 82$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PG1IH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains $7$ values with a mean of $39$. When an $8$th value is added, the new mean becomes $42$. What is the $8$th value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '63', ARRAY['63'], E'The sum of the original $7$ values is $7 \\times 39 = 273$. With $8$ values and a mean of $42$, the new sum is $8 \\times 42 = 336$. The $8$th value is $336 - 273 = 63$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PJQAY7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A hemisphere with diameter $18$ has the same volume as a cone with base radius $9$. What is the height of the cone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'The hemisphere has radius $\\frac{18}{2} = 9$. The volume of a hemisphere is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi (9)^3 = \\frac{2}{3}\\pi (729) = 486\\pi$. The volume of a cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi (9)^2 h = \\frac{1}{3}\\pi (81) h = 27\\pi h$. Setting these equal: $486\\pi = 27\\pi h$, so $h = \\frac{486}{27} = 18$. A common error is using the diameter $18$ as the hemisphere''s radius, which yields a hemisphere volume of $\\frac{2}{3}\\pi(18)^3 = 3888\\pi$ and a cone height of $144$. Another error is using $\\frac{4}{3}\\pi r^3$ (the full sphere formula) instead of $\\frac{2}{3}\\pi r^3$ for the hemisphere, which doubles the result to $h = 36$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PO2ZNM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $f$ is linear. If $f(3) - f(1) = 14$ and $f(6) = 50$, what is $f(0)$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Since $f$ is linear, $f(x) = mx + b$ for some constants $m$ and $b$. The condition $f(3) - f(1) = (3m + b) - (m + b) = 2m = 14$ gives $m = 7$. Using $f(6) = 50$: $6(7) + b = 42 + b = 50$, so $b = 8$. Therefore $f(0) = b = 8$. Verification: $f(x) = 7x + 8$, so $f(3) = 29$, $f(1) = 15$, $f(3) - f(1) = 14$, and $f(6) = 50$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PW20AL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution set of the equation $\\sqrt{6x + 19} = x + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$\\{-3\\}$"},{"key":"B","text":"$\\{-3, 5\\}$"},{"key":"C","text":"$\\{5\\}$"},{"key":"D","text":"$\\{-5\\}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Squaring both sides gives $6x + 19 = (x + 2)^2 = x^2 + 4x + 4$. Rearranging: $x^2 - 2x - 15 = 0$, which factors as $(x - 5)(x + 3) = 0$, yielding $x = 5$ or $x = -3$. Checking $x = 5$: $\\sqrt{6(5) + 19} = \\sqrt{49} = 7$ and $5 + 2 = 7$, which is valid. Checking $x = -3$: $\\sqrt{6(-3) + 19} = \\sqrt{1} = 1$ and $-3 + 2 = -1$, so $1 \\neq -1$ and this solution is extraneous. The only valid solution is $x = 5$. The distractor $\\{-3\\}$ results from selecting the extraneous solution and discarding the valid one. The distractor $\\{-3, 5\\}$ results from finding both algebraic solutions but failing to check for extraneous roots introduced by squaring. The distractor $\\{-5\\}$ results from a sign error when solving the factor $x - 5 = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q0HZJC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on daily high temperature (in $°F$) and the number of ice cream cones sold at a stand. The line of best fit is $y = 3.2x - 147$, where $x$ is the temperature and $y$ is the number of cones sold. What is the best interpretation of the slope $3.2$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each $1°F$ increase in temperature, the predicted number of cones sold increases by $3.2$."},{"key":"B","text":"For each additional cone sold, the predicted temperature increases by $3.2°F$."},{"key":"C","text":"When the temperature is $0°F$, the predicted number of cones sold is $3.2$."},{"key":"D","text":"The stand sells $3.2$ cones at the average temperature."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable ($y$, cones sold) for each one-unit increase in the independent variable ($x$, temperature). So $3.2$ means for each $1°F$ increase in temperature, the predicted number of cones sold increases by $3.2$. The distractor reversing the variables incorrectly swaps the roles of $x$ and $y$. The distractor describing the value at $0°F$ confuses slope with the $y$-intercept. The distractor about average temperature has no relationship to the slope''s meaning.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QFLT8E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In triangle $ABC$, angle $B$ is a right angle. If $\\tan(A) = \\frac{39}{80}$ and $BC = 39$, what is the area of triangle $ABC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1560', ARRAY['1560'], E'Since angle $B$ is a right angle, the legs are $\\overline{AB}$ and $\\overline{BC}$. We have $\\tan(A) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{BC}{AB} = \\frac{39}{AB}$. Setting this equal to $\\frac{39}{80}$ gives $AB = 80$. The area of the right triangle is $\\frac{1}{2} \\times AB \\times BC = \\frac{1}{2} \\times 80 \\times 39 = 1560$. A common error is forgetting the factor of $\\frac{1}{2}$, yielding $3120$. Another error is confusing tangent with sine and computing $AB$ from $\\sin(A) = \\frac{39}{80}$, which gives an incorrect leg length and area.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QZVSQI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = (x + 9)^2 - 17$ is defined for all real numbers $x$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-17$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$9$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x + 9)^2 - 17$ is in vertex form $a(x - h)^2 + k$ with $a = 1$, $h = -9$, and $k = -17$. Since the coefficient of the squared term is positive, the parabola opens upward and the minimum value is $k = -17$, occurring at $x = -9$. The distractor $-9$ comes from confusing the $x$-coordinate of the vertex (where the minimum occurs) with the minimum value itself. The distractor $9$ results from taking the positive value of $h$ due to a sign error in reading the vertex form. The distractor $17$ results from ignoring the negative sign on the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RHH8FA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A market researcher surveys 1,200 randomly selected adults in a city and finds that $29\\%$ regularly purchase organic produce. The margin of error is $\\pm 2.3\\%$. The researcher claims that fewer than one-third of all adults in the city regularly purchase organic produce. Is the researcher''s claim supported by the data?', NULL, $lyceon_json$[{"key":"A","text":"Yes, because the sample percentage of $29\\%$ is less than $33.\\overline{3}\\%$."},{"key":"B","text":"Yes, because the entire confidence interval falls below $33.\\overline{3}\\%$."},{"key":"C","text":"No, because $31.3\\%$ is close enough to $33.\\overline{3}\\%$ that the true value could be one-third."},{"key":"D","text":"No, because the margin of error means the true value could be as high as $33.6\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $29\\% - 2.3\\% = 26.7\\%$ to $29\\% + 2.3\\% = 31.3\\%$. Since the entire confidence interval ($26.7\\%$ to $31.3\\%$) lies below $33.\\overline{3}\\%$ (one-third), the data supports the researcher''s claim. The option stating that $29\\%$ is less than one-third is true but uses only the sample statistic without accounting for the margin of error — the claim is supported only because the entire interval is below the threshold, not merely the point estimate. The option asserting that $31.3\\%$ is "close enough" to one-third confuses proximity with the interval actually containing the value; $31.3\\%$ is below $33.\\overline{3}\\%$, so one-third is not within the interval. The option citing $33.6\\%$ as the upper bound results from incorrectly computing $29\\% + 4.6\\% = 33.6\\%$ instead of $29\\% + 2.3\\% = 31.3\\%$, effectively doubling the margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RQXUIQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher finds that counties with more public libraries per capita tend to have higher median household incomes. The researcher concludes that building additional libraries will cause household incomes to rise. Which of the following is the most significant flaw in the researcher''s reasoning?', NULL, $lyceon_json$[{"key":"A","text":"The sample of counties may not have been randomly selected, so the results may not generalize."},{"key":"B","text":"The relationship may be explained by a third variable, such as overall community wealth, that independently influences both the number of libraries and household incomes."},{"key":"C","text":"The researcher should have surveyed individual residents rather than using county-level data."},{"key":"D","text":"A larger sample of counties would be needed to detect a real relationship."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study — the researcher observed existing data without randomly assigning counties to build or not build libraries. In observational studies, a correlation between two variables does not establish that one causes the other because a confounding variable may drive both. Wealthier communities may independently have both more libraries and higher incomes, producing the observed association without any causal link from libraries to income. While non-random sampling and sample size are legitimate concerns, they do not address the core flaw of drawing a causal conclusion from observational data. Suggesting individual-level data is needed confuses the unit of analysis with the study design problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SHVDOP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $5$ centimeters and a height of $11$ centimeters. What is the volume, in cubic centimeters, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$55\\pi$"},{"key":"B","text":"$110\\pi$"},{"key":"C","text":"$275\\pi$"},{"key":"D","text":"$550\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (5)^2 (11) = 275\\pi$ cubic centimeters. The value $55\\pi$ results from computing $\\pi r h = \\pi(5)(11)$ without squaring the radius. The value $110\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(5)(11) = 110\\pi$ instead of the volume formula. The value $550\\pi$ results from doubling the correct volume, perhaps by confusing the radius with the diameter and computing $\\pi(10)(5)(11)$ or a similar error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T12VUX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A researcher surveys 350 randomly selected adults in a city and finds that $53\\%$ approve of a proposed zoning policy. The survey has a margin of error of $\\pm 3\\%$. Based on this survey, which of the following could plausibly be the true percentage of all adults in the city who approve of the policy?', NULL, $lyceon_json$[{"key":"A","text":"$47\\%$"},{"key":"B","text":"$55\\%$"},{"key":"C","text":"$58\\%$"},{"key":"D","text":"$64\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $53\\% - 3\\% = 50\\%$ to $53\\% + 3\\% = 56\\%$. A plausible value for the true percentage must fall within this interval. The value $55\\%$ falls within $[50\\%, 56\\%]$ and is therefore plausible. The value $47\\%$ is below the lower bound of $50\\%$ and falls outside the interval. The value $58\\%$ exceeds the upper bound of $56\\%$, arising from mistakenly adding $5$ instead of $3$ to the sample statistic. The value $64\\%$ is well outside the interval, resulting from an error such as doubling the margin.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TIENRX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is the completely factored form of $12x^3 + 20x^2 - 8x$?', NULL, $lyceon_json$[{"key":"A","text":"$2x(3x - 1)(2x + 4)$"},{"key":"B","text":"$4x(3x - 1)(x + 2)$"},{"key":"C","text":"$4x(3x + 1)(x - 2)$"},{"key":"D","text":"$4x(3x + 2)(x - 1)$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, factor out the greatest common factor $4x$: $12x^3 + 20x^2 - 8x = 4x(3x^2 + 5x - 2)$. Then factor the trinomial by finding two numbers whose product is $3 \\times (-2) = -6$ and whose sum is $5$: those are $6$ and $-1$. Rewriting: $3x^2 + 6x - x - 2 = (3x - 1)(x + 2)$. So the completely factored form is $4x(3x - 1)(x + 2)$. The distractor $2x(3x - 1)(2x + 4)$ is equivalent to the original expression but is not completely factored because $2x + 4 = 2(x + 2)$, leaving a factor of $2$ that should be extracted. The distractor $4x(3x + 1)(x - 2)$ results from a sign error in the binomial factors, producing $3x^2 - 5x - 2$ instead of $3x^2 + 5x - 2$. The distractor $4x(3x + 2)(x - 1)$ expands to $4x(3x^2 - x - 2) = 12x^3 - 4x^2 - 8x$, which arises from using an incorrect factor pair for the trinomial.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TPOPZB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$ with the right angle at $F$, $\\sin(D) = \\frac{48}{73}$. What is the value of $\\cos(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{25}{73}$"},{"key":"B","text":"$\\frac{48}{55}$"},{"key":"C","text":"$\\frac{55}{73}$"},{"key":"D","text":"$\\frac{55}{48}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the Pythagorean identity $\\sin^2(D) + \\cos^2(D) = 1$, we get $\\cos^2(D) = 1 - \\left(\\frac{48}{73}\\right)^2 = 1 - \\frac{2304}{5329} = \\frac{3025}{5329}$. Taking the positive square root (since $D$ is an acute angle), $\\cos(D) = \\frac{55}{73}$. The value $\\frac{25}{73}$ results from subtracting the numerators ($73 - 48 = 25$) instead of using the identity. The value $\\frac{48}{55}$ results from confusing cosine with tangent, computing $\\frac{\\text{opposite}}{\\text{adjacent}}$. The value $\\frac{55}{48}$ results from computing the adjacent side correctly but placing it over the opposite side instead of the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2USLBN0', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $7x + 35 = 91$ ?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$8$"},{"key":"C","text":"$10$"},{"key":"D","text":"$56$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtract $35$ from both sides of $7x + 35 = 91$ to get $7x = 56$. Divide both sides by $7$ to get $x = 8$. The value $6$ results from an arithmetic slip when dividing $56$ by $7$. The value $10$ comes from rounding $91 \\div 7 \\approx 13$ and subtracting $3$ instead of $5$, or another computational error. The value $56$ results from subtracting $35$ but forgetting to divide by $7$, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UVN5XG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'Machine A produces $47$ bolts per minute, and Machine B produces $31$ bolts per minute. Machine A runs for $t$ minutes, and Machine B runs for $(t + 14)$ minutes. If the two machines produce the same total number of bolts, what is the value of $t$?', NULL, $lyceon_json$[{"key":"A","text":"$27.125$"},{"key":"B","text":"$24$"},{"key":"C","text":"$31$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the total bolts equal: $47t = 31(t + 14)$. Expanding: $47t = 31t + 434$. Subtracting $31t$: $16t = 434$. Dividing: $t = \\frac{434}{16} = 27.125$. The distractor $24$ comes from an arithmetic error in dividing $434 \\div 16$ and rounding incorrectly. The distractor $31$ comes from confusing Machine B''s rate with the answer. The distractor $14$ comes from using the extra time directly without solving the equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W42X2I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe requires $\\frac{3}{4}$ cup of sugar for every $\\frac{5}{8}$ cup of butter. If a baker uses $2$ cups of butter, how many cups of sugar does the baker need?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{12}{5}$"},{"key":"B","text":"$\\frac{5}{3}$"},{"key":"C","text":"$\\frac{3}{2}$"},{"key":"D","text":"$\\frac{15}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The ratio of sugar to butter is $\\frac{3/4}{5/8} = \\frac{3}{4} \\times \\frac{8}{5} = \\frac{24}{20} = \\frac{6}{5}$. For $2$ cups of butter: $\\frac{6}{5} \\times 2 = \\frac{12}{5}$ cups of sugar. The distractor $\\frac{5}{3}$ comes from inverting the ratio to $\\frac{5/8}{3/4} = \\frac{5}{6}$ and then multiplying by $2$. The distractor $\\frac{3}{2}$ comes from simply doubling $\\frac{3}{4}$ without using the correct proportion. The distractor $\\frac{15}{8}$ comes from multiplying $\\frac{3}{4} \\times \\frac{5}{8} \\times 2$ instead of dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WECELV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line that passes through the points $(-3, 8)$ and $(5, -4)$ ?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{2}$"},{"key":"B","text":"$-\\frac{2}{3}$"},{"key":"C","text":"$\\frac{2}{3}$"},{"key":"D","text":"$\\frac{3}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-4 - 8}{5 - (-3)} = \\frac{-12}{8} = -\\frac{3}{2}$. The value $-\\frac{2}{3}$ results from inverting the slope formula to $\\frac{\\Delta x}{\\Delta y}$ instead of $\\frac{\\Delta y}{\\Delta x}$. The value $\\frac{2}{3}$ results from both inverting the formula and dropping the negative sign. The value $\\frac{3}{2}$ results from computing the correct magnitude but losing the negative sign, for instance by subtracting the coordinates in inconsistent orders ($\\frac{8 - (-4)}{5 - (-3)} = \\frac{12}{8}$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XSAZWG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'What is the radius of the circle with equation $x^2 + y^2 + 14x - 6y + 22 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$\\sqrt{22}$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square. Group the $x$ and $y$ terms: $(x^2 + 14x) + (y^2 - 6y) = -22$. Complete each square: $(x^2 + 14x + 49) + (y^2 - 6y + 9) = -22 + 49 + 9 = 36$. This gives $(x + 7)^2 + (y - 3)^2 = 36$, so $r^2 = 36$ and $r = 6$. The value $\\sqrt{22}$ results from incorrectly using the constant term $22$ as $r^2$ without completing the square. The value $36$ results from finding $r^2 = 36$ but not taking the square root. The value $3$ results from an arithmetic error in completing the square, such as forgetting to add both correction terms to the right side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YAQ14B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $XYZ$, the measure of angle $X$ is $47^\\circ$ and the measure of angle $Y$ is $62^\\circ$. What is the measure, in degrees, of angle $Z$?', NULL, $lyceon_json$[{"key":"A","text":"$51$"},{"key":"B","text":"$61$"},{"key":"C","text":"$71$"},{"key":"D","text":"$109$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Therefore, the measure of angle $Z$ is $180 - 47 - 62 = 71^\\circ$. The value $109$ results from computing $47 + 62$ and stopping, mistaking the sum of two angles for the third. The value $61$ results from an arithmetic error when subtracting $109$ from $180$. The value $51$ results from a subtraction error such as misreading $47$ as $67$ and computing $180 - 67 - 62$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW200BY8U', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two authors interpret the same phenomenon?', E'Text 1: Neuroscientist Ravi Anand has proposed that the human tendency to anthropomorphize non-human entities—attributing emotions, intentions, and personality traits to animals, machines, and natural forces—reflects an adaptive cognitive mechanism. By defaulting to social reasoning when encountering ambiguous stimuli, Anand argues, early humans could more quickly detect potential threats and allies in their environment.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20W3AGT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Computational linguist Maria Pérez-Ortiz has argued that large language models do not truly acquire syntactic rules but instead exploit statistical regularities in their training data to approximate grammatical output. Her 2024 study showed that when tested on sentence structures absent from their training corpora, three leading models produced grammatically incoherent responses at rates above 60 percent. _______ Pérez-Ortiz acknowledges that these models'' performance on familiar sentence types is often indistinguishable from that of human speakers, a fact she attributes to the sheer volume of patterns the models internalize rather than to genuine rule learning.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentences present evidence that language models fail on unfamiliar syntactic structures, supporting the claim that they lack true syntactic knowledge. The final sentence then concedes that on familiar structures these models perform comparably to humans, which partially qualifies the criticism. This shift from a negative finding to a concession requires a transition that signals acknowledgment of a counterpoint. The option meaning ''more precisely'' is wrong because the final sentence does not narrow or clarify the 60 percent failure rate; it introduces a separate observation about familiar-structure performance. The option meaning ''in addition'' is wrong because the final sentence does not add a supporting point to the critique; it partially softens the criticism by recognizing the models'' strengths. The option meaning ''as a consequence'' is wrong because strong performance on familiar structures is not caused by failure on unfamiliar ones; the two observations are independent findings that pull in different directions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21FU69B', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since the early 1900s. Its short reproductive cycle allows researchers to observe hereditary changes across many generations in a matter of weeks. __More recently, scientists have begun using Drosophila to study the genetic basis of sleep regulation, discovering that many of the same genes involved in human sleep disorders also appear in the fly''s genome.__ This finding has opened new avenues for pharmaceutical research targeting insomnia and related conditions.', $lyceon_json$[{"key":"A","text":"To introduce a newer application of a well-established research organism"},{"key":"B","text":"To challenge a widely held assumption about fruit fly genetics"},{"key":"C","text":"To provide biographical details about the scientists who study Drosophila"},{"key":"D","text":"To argue that fruit flies are superior to other model organisms"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first establishes the fruit fly as a long-used genetics tool, and the underlined sentence then pivots to describe a recent, different use of the same organism in sleep research. This makes the function an introduction of a newer application of a well-established subject. The option about challenging an assumption is wrong because the sentence extends the fly''s uses rather than disputing any prior claim. The option about biographical details is wrong because no personal information about scientists appears. The option about arguing superiority is wrong because no comparison to other organisms is made.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22BEQOS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The architect Lina Bo Bardi rejected the idea that buildings should be treated as static monuments. Her design for the São Paulo Museum of Art, completed in 1968, suspended the main exhibition hall above an open civic plaza, deliberately leaving the ground level unenclosed so that the public could move freely beneath the structure. _______ Bo Bardi intended her later project, the SESC Pompeia leisure center, to evolve with its community: she incorporated flexible interior partitions and left certain walls unfinished, inviting future occupants to reshape the spaces.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"In a similar vein,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'C', NULL, E'Both the São Paulo Museum and the SESC Pompeia center illustrate Bo Bardi''s rejection of static, monumental architecture: the first through open ground-level design, the second through adaptable partitions and unfinished walls. The passage introduces a second example that parallels the first, so the transition indicating a comparable idea is correct. The option meaning ''to restate the same point'' is wrong because the third sentence introduces a distinct project with different design strategies rather than rephrasing the museum example. The option signaling contrast is wrong because both projects advance the same architectural philosophy rather than opposing each other. The option indicating causation is wrong because the SESC Pompeia project is not a consequence of the museum''s design; it is an independent expression of the same principle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22LNNZA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 study published in the journal Ecology Letters, researchers examined how urbanization affects pollinator populations. The evidence collected across forty-seven metropolitan areas _____ that native bee species decline sharply when green corridors between parks are narrower than three hundred meters.', $lyceon_json$[{"key":"A","text":"suggests"},{"key":"B","text":"suggest"},{"key":"C","text":"are suggesting"},{"key":"D","text":"have suggested"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the clause is "evidence," which is a singular uncountable noun. The prepositional phrase "collected across forty-seven metropolitan areas" modifies "evidence" but does not change its number — the plural noun "areas" within the prepositional phrase is not the subject. The singular present-tense verb "suggests" correctly agrees with the singular subject "evidence" and matches the present-tense context established by the passage''s discussion of findings. The bare plural "suggest" does not agree with the singular subject. The plural progressive "are suggesting" fails on number agreement. The plural perfect "have suggested" also fails on number agreement with the singular uncountable noun "evidence."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23M8TU4', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1: Linguist Yolanda Ferreira argues that endangered languages should be documented through immersive community partnerships in which linguists live among speakers for extended periods, participating in daily routines and ceremonial practices. Ferreira maintains that only this embedded approach can capture the pragmatic and contextual dimensions of language—tone, gesture, situational register—that are lost when documentation relies primarily on elicitation sessions and structured interviews. She warns that efficiency-driven methods, however well-intentioned, risk producing archives that preserve vocabulary and grammar while stripping away the communicative ecology that gives a language its vitality.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24OSPXB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if included in the text, would most effectively support the claim about Hurston''s narrative technique?', E'Zora Neale Hurston''s 1937 novel Their Eyes Were Watching God is celebrated for its innovative use of free indirect discourse, a narrative technique in which the narrator''s voice merges with a character''s interior thoughts without explicit attribution. Rather than writing ''Janie thought that the horizon seemed close enough to touch,'' Hurston renders the moment through Janie''s own idiom while maintaining third-person narration: ''She had been getting ready for her great journey to the horizons in search of people.'' Literary scholars argue that this technique allows Hurston to honor the oral traditions of Black Southern speech while simultaneously granting Janie a psychological depth that conventional third-person narration rarely achieves.', $lyceon_json$[{"key":"A","text":"\"Hurston's dialogue captures the rhythms of Eatonville's porch talk with remarkable phonetic accuracy, preserving a vanishing dialect for future readers.\""},{"key":"B","text":"\"By weaving Janie's vernacular consciousness into the fabric of the narration itself, Hurston dissolves the boundary between character thought and narrative authority.\""},{"key":"C","text":"\"Their Eyes Were Watching God was largely ignored by the Harlem Renaissance literary establishment, which favored protest fiction over folk narrative.\""},{"key":"D","text":"\"Hurston's anthropological fieldwork in the rural South provided the raw material for many of the novel's most vivid settings and secondary characters.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The passage claims that Hurston''s free indirect discourse merges the narrator''s voice with Janie''s interior thoughts. The quotation about weaving vernacular consciousness into the narration and dissolving the boundary between character thought and narrative authority directly supports this claim about the technique. The quotation about capturing porch-talk dialect addresses dialogue accuracy rather than the narrative technique of free indirect discourse. The quotation about the novel being ignored by the literary establishment concerns the book''s reception, not its narrative method. The quotation about anthropological fieldwork relates to Hurston''s source material, not to her narrative technique.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24THUSH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Economists have long debated whether minimum-wage increases reduce employment among low-wage workers. A landmark 1994 study by David Card and Alan Krueger examined fast-food restaurants along the New Jersey–Pennsylvania border after New Jersey raised its minimum wage from $4.25 to $5.05 per hour. Contrary to the standard competitive-market prediction, employment in New Jersey''s fast-food sector did not decline relative to Pennsylvania''s. Card and Krueger proposed that the market had monopsonistic features—employers possessed wage-setting power that allowed them to pay below the competitive equilibrium, and the minimum-wage increase simply moved wages closer to that equilibrium without triggering layoffs.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24UZ34L', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 monograph on Renaissance patronage networks, historian Eleanora Voss argues that the Medici family''s cultural influence has been ______ by scholars who focus exclusively on their financial contributions to the arts, thereby overlooking the complex web of political alliances and social obligations that actually drove artistic commissions in fifteenth-century Florence.', $lyceon_json$[{"key":"A","text":"oversimplified"},{"key":"B","text":"undermined"},{"key":"C","text":"authenticated"},{"key":"D","text":"discontinued"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes scholars who reduce the Medici influence to a single dimension (financial contributions) while missing a broader, more complex picture. A word meaning reduced to an excessively simple form captures this idea precisely. The option meaning weakened or sabotaged implies the scholars damaged the Medici influence itself rather than produced an incomplete account of it. The option meaning verified as genuine reverses the passage''s critical stance toward these scholars. The option meaning stopped or ended suggests the influence was halted, which contradicts the passage''s focus on how the influence is characterized rather than whether it persists.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW257RIGC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Researchers studying the migration patterns of Arctic terns have long been ______ by the birds'' ability to navigate across hemispheres with remarkable accuracy, despite lacking any technological aids. Recent tagging studies have only deepened this sense of wonder among ornithologists.', $lyceon_json$[{"key":"A","text":"astonished"},{"key":"B","text":"irritated"},{"key":"C","text":"burdened"},{"key":"D","text":"delayed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes researchers experiencing a sense of wonder at the birds'' navigational abilities, which deepened over time. The word meaning struck with amazement fits this context precisely. The option suggesting annoyance contradicts the passage''s tone of admiration. The option meaning weighed down introduces a negative physical connotation absent from the passage. The option meaning slowed implies a temporal obstacle, which is unrelated to the researchers'' emotional response.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25GZFAV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Cellist and composer Okwui Enwezor-Diaz has spent years blending West African rhythmic traditions with European chamber music forms. Her latest album features seven original compositions, each of which _____ a different tuning system derived from the overtone patterns of traditional igbin drums.', $lyceon_json$[{"key":"A","text":"employs"},{"key":"B","text":"employ"},{"key":"C","text":"employing"},{"key":"D","text":"are employing"}]$lyceon_json$::jsonb, 'A', NULL, E'The relative clause "each of which" requires a singular verb because "each" is the subject. Although "which" refers to the plural antecedent "compositions," the pronoun "each" distributes the predicate individually and is grammatically singular. The singular verb "employs" correctly agrees with "each." The plural verb "employ" incorrectly treats "which" or "compositions" as the subject rather than "each." The present participle "employing" is not a finite verb and would create a sentence fragment, leaving the relative clause without a main verb. The plural progressive "are employing" fails on number agreement, since "each" requires a singular verb form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27OF3XJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Voyager 1 spacecraft, launched by NASA in 1977 to study the outer planets of the solar system, _____ now the most distant human-made object from Earth, having crossed into interstellar space in 2012.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "The Voyager 1 spacecraft," which is singular. The phrase "launched by NASA in 1977 to study the outer planets of the solar system" is a participial phrase set off by commas that modifies the subject but does not change its number. The singular present-tense verb "is" correctly agrees with the singular subject and reflects the spacecraft''s current status. The plural verb "are" does not agree with the singular subject. The past-tense plural verb "were" fails on both number and tense, since the sentence describes a present condition. The present-perfect plural "have been" also fails on number agreement with the singular subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BGEEDT', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Coral bleaching events have increased in frequency over the past four decades, with water temperatures in some tropical reef systems rising by nearly 1.5 degrees Celsius since 1983. Marine biologist Tara Okonkwo has proposed that certain coral species possess a previously unrecognized capacity for thermal adaptation: by harboring heat-tolerant strains of symbiotic algae, these corals can withstand temperatures that would kill less adaptable colonies. Okonkwo acknowledges, however, that this mechanism has limits and cannot compensate for the sustained warming trends projected under current emissions scenarios.', $lyceon_json$[{"key":"A","text":"It presents a problem, introduces a researcher's partial explanation, and then notes that explanation's limitations"},{"key":"B","text":"It compares two competing scientific theories and concludes that neither is fully supported by evidence"},{"key":"C","text":"It describes a natural phenomenon, traces its historical origins, and predicts its future disappearance"},{"key":"D","text":"It proposes a solution to an environmental crisis and refutes objections raised by other scientists"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage opens by describing the increasing problem of coral bleaching, then introduces Okonkwo''s explanation that some corals can adapt through heat-tolerant algae, and finally acknowledges limits to this mechanism. This three-part movement matches the option describing a problem, a partial explanation, and its limitations. The option about two competing theories is wrong because only one researcher''s view is presented. The option about predicting future disappearance is wrong because the passage does not claim coral bleaching will vanish. The option about proposing a solution and refuting objections is wrong because Okonkwo herself raises the qualification rather than defending against external critics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C3Z1H6', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2023 survey conducted across eleven European nations, 68 percent of respondents said they trusted locally grown produce more than imported alternatives. _______ a parallel study by the same research group found that consumers in those same countries purchased imported fruits and vegetables at nearly twice the rate of domestic ones when the price difference exceeded 19 percent.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that consumers express a preference for locally grown produce, while the second sentence reveals that their purchasing behavior contradicts that stated preference when price differences are large enough. This tension between stated trust and actual buying patterns requires a concessive or contrastive transition. The option meaning ''in addition'' is wrong because the second sentence does not reinforce the first but instead undermines it. The option indicating a result is wrong because the second finding is not caused by the first; it contradicts it. The option meaning ''in the same way'' is wrong because the two findings point in opposite directions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DM4HUW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they shelter roughly one quarter of all known marine species. Marine biologist Elara Montoya has documented how the structural complexity of reef formations—branching corals, crevices, and overhangs—creates microhabitats that sustain this outsized biodiversity. Montoya''s surveys across seventeen reef sites in the western Pacific found that reefs with greater three-dimensional complexity harbored up to forty-three percent more fish species than structurally simpler reefs nearby. Her findings reinforce the view that preserving reef architecture, not merely reef area, is essential for maintaining marine biodiversity.', $lyceon_json$[{"key":"A","text":"Coral reefs support a disproportionately large share of marine biodiversity, and research indicates that the structural complexity of reefs is a key factor in sustaining that biodiversity."},{"key":"B","text":"Elara Montoya conducted surveys at seventeen reef sites in the western Pacific to compare fish populations in different ocean regions."},{"key":"C","text":"Coral reefs are threatened by climate change, and scientists are working to develop strategies for restoring damaged reef ecosystems."},{"key":"D","text":"Marine biodiversity is declining worldwide because coral reefs are losing structural complexity due to human activity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the relationship between coral reef structural complexity and biodiversity, supported by Montoya''s research. The correct answer captures this main idea: reefs support outsized biodiversity, and their three-dimensional architecture is critical. The option about Montoya''s seventeen-site surveys focuses on a supporting detail rather than the central idea. The option about climate change threats introduces a topic never mentioned in the passage. The option about worldwide biodiversity decline due to human activity goes beyond anything stated in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E8OIA2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing about the dietary habits of the Virginia opossum for a wildlife biology class. The student wants to emphasize the breadth of the opossum''s diet. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FG0BDK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Kenji Adachi has spent over a decade studying the migratory patterns of leatherback sea turtles in the western Pacific. His research has revealed that these turtles travel thousands of miles each year, crossing multiple national _____ Adachi advocates for international cooperation to protect the turtles'' migratory corridors.', $lyceon_json$[{"key":"A","text":"boundaries,"},{"key":"B","text":"boundaries"},{"key":"C","text":"boundaries, Adachi"},{"key":"D","text":"boundaries."}]$lyceon_json$::jsonb, 'D', NULL, E'The passage contains two independent clauses that should be separated by a period. Using no punctuation between the clauses creates a run-on sentence. Using only a comma between the clauses without a coordinating conjunction creates a comma splice, a sentence boundary error. Using a comma followed by the subject of the next clause also creates a comma splice. A period correctly ends the first sentence and begins the second.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G3B7J5', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The painted lady butterfly (Vanessa cardui) undertakes one of the longest known insect migrations, traveling up to 15,000 kilometers between sub-Saharan Africa and Scandinavia across multiple generations. Unlike monarch butterflies, which follow well-documented routes along the North American coasts, painted ladies disperse broadly across continents and fly at altitudes above 500 meters, making them difficult to track with ground-based observation. Consequently, until radar entomology studies in the 2010s revealed the scale of painted lady movements over Europe, most researchers ________', $lyceon_json$[{"key":"A","text":"had significantly underestimated the distances that painted lady butterflies travel during migration."},{"key":"B","text":"had focused primarily on the conservation status of painted lady populations in sub-Saharan Africa."},{"key":"C","text":"had concluded that painted ladies were incapable of sustained flight over open water."},{"key":"D","text":"had developed sophisticated models predicting the exact timing of painted lady arrivals in Scandinavia."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that painted ladies were difficult to track from the ground and that radar studies revealed the scale of their movements. The logical inference is that before radar evidence, researchers underestimated how far these butterflies travel. The option about focusing on conservation status in sub-Saharan Africa introduces a topic not discussed in the passage. The option about sustained flight over open water introduces a specific claim the passage never addresses. The option about sophisticated prediction models contradicts the passage''s point that tracking was difficult before radar technology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GRI62H', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Entomologists at the University of Bern have hypothesized that the dramatic decline of wild bee populations in alpine meadows above 1,800 meters is driven primarily by a reduction in floral diversity rather than by changes in temperature. Their preliminary field observations noted that meadows where livestock grazing had been recently discontinued showed both greater wildflower variety and higher bee abundance than adjacent grazed meadows at the same elevation, but the researchers acknowledged that other variables could explain the pattern.', $lyceon_json$[{"key":"A","text":"Alpine meadows that experienced a two-degree increase in average summer temperature over a decade showed no significant change in bee populations."},{"key":"B","text":"Wild bee species in alpine regions are genetically distinct from bee populations at lower elevations."},{"key":"C","text":"Livestock grazing has been practiced in alpine meadows for over three hundred years with little variation in technique."},{"key":"D","text":"The species of wildflowers found in ungrazed meadows bloom earlier in the season than those in grazed meadows."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis is that floral diversity loss, not temperature change, drives bee decline. A finding that temperature increases did not affect bee populations would weaken the alternative explanation (temperature) and thereby strengthen the floral-diversity hypothesis. The option about genetic distinctness of alpine bees is irrelevant to the question of what drives population decline. The option about the long history of grazing practices does not address whether floral diversity or temperature is the primary driver. The option about bloom timing describes a difference between grazed and ungrazed meadows but does not directly address the central hypothesis about floral diversity versus temperature as the cause of bee decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HHDKMF', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeologist Priya Venkatesh has uncovered evidence suggesting that the ancient city of Dholavira, located on an island in Gujarat''s Rann of Kutch, maintained an elaborate water management system. The city''s residents constructed reservoirs and channels to capture seasonal _____ this engineering achievement allowed the settlement to thrive in an otherwise arid landscape for nearly fifteen hundred years.', $lyceon_json$[{"key":"A","text":"rainfall; consequently,"},{"key":"B","text":"rainfall, consequently,"},{"key":"C","text":"rainfall; nonetheless,"},{"key":"D","text":"rainfall consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses with a cause-effect relationship are joined here. A semicolon followed by the conjunctive adverb ''consequently'' and a comma correctly links them. Using a comma before ''consequently'' without a coordinating conjunction creates a comma splice, a sentence boundary error. Using ''nonetheless'' after a semicolon produces a grammatically correct structure but the wrong logical relationship, since ''nonetheless'' signals contrast rather than consequence. Omitting the semicolon before ''consequently'' creates a run-on sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LP0PO2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In the early twentieth century, physicists assumed that cosmic rays—high-energy particles bombarding Earth from space—originated within our own galaxy. This assumption went largely unchallenged until 1962, when physicist John Linsley detected a cosmic ray with an energy exceeding 100 quintillion electron volts, far surpassing what any known galactic source could produce. Linsley''s detection implied that some cosmic rays must originate from extraordinarily powerful extragalactic events. Yet even after Linsley''s finding, many physicists remained skeptical, noting that a theoretical energy limit proposed by Kenneth Greisen, Georgiy Zatsepin, and Vadim Kuzmin—the GZK limit—predicted that cosmic rays above a certain energy threshold would lose energy through interactions with the cosmic microwave background radiation before reaching Earth from distant sources. If the GZK limit held, then ________', $lyceon_json$[{"key":"A","text":"the highest-energy cosmic rays would need to originate from sources relatively close to Earth, not from remote extragalactic objects."},{"key":"B","text":"all cosmic rays detected on Earth would have identical energy levels regardless of their point of origin."},{"key":"C","text":"extragalactic cosmic rays would arrive at Earth with higher energies than cosmic rays from galactic sources."},{"key":"D","text":"the cosmic microwave background radiation would intensify in regions where cosmic ray activity is highest."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that the GZK limit predicts high-energy cosmic rays would lose energy interacting with the cosmic microwave background over long distances. The logical completion is that if this limit held, the highest-energy cosmic rays reaching Earth would need to come from nearby sources rather than distant extragalactic ones. The option claiming identical energy levels regardless of origin contradicts basic physics and overstates what the GZK limit implies. The option about extragalactic rays arriving with higher energies contradicts the GZK limit, which predicts energy loss over distance. The option about cosmic microwave background intensifying near cosmic ray activity reverses the causal relationship described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OWOU0Y', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the table, if accurate, would most directly undermine the researchers'' conclusion?', E'A team of nutritional scientists at the University of Groningen studied the relationship between fermented food consumption and gut microbiome diversity in 1,247 adults over a fourteen-month period. Participants who consumed at least three servings of fermented foods per week—such as kefir, sauerkraut, or kimchi—showed a statistically significant increase in gut microbial species richness compared to a control group that maintained their usual diet. The researchers concluded that regular fermented food consumption directly enhances gut microbiome diversity. However, the study relied on self-reported dietary logs, and participants were not randomly assigned to diet groups.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PWJFXP', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the kelp forests off the coast of Tasmania observed a 37 percent decline in canopy coverage between 2001 and 2019. _______ the researchers documented a corresponding drop in the populations of weedy sea dragons and other species that depend on kelp for shelter.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes a consequence that follows logically from the decline in kelp canopy coverage described in the first sentence: fewer kelp forests led to fewer species that depend on kelp. The transition indicating a logical result is the correct choice. The option suggesting contrast is wrong because both sentences describe negative ecological trends rather than opposing ideas. The option suggesting illustration is wrong because the second sentence is not an example of canopy decline but a separate effect. The option suggesting simultaneity fails because the relationship is cause-and-effect, not mere co-occurrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QX6LB6', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'In a 2021 paper, economist Priya Narayanan examined wage growth data from 37 mid-sized American cities between 2004 and 2018. She found that cities with higher concentrations of unionized public-sector workers experienced wage gains that outpaced inflation by an average of 2.3 percentage points, even after controlling for regional cost-of-living differences and industry composition.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RFH4BQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason that Khmer engineers constructed the baray system?', E'The Khmer Empire, centered at Angkor in present-day Cambodia, engineered one of the premodern world''s most elaborate hydraulic systems. Between the ninth and thirteenth centuries, Khmer engineers constructed enormous rectangular reservoirs called barays, the largest of which—the West Baray—stretched roughly eight kilometers long and held over fifty million cubic meters of water. These reservoirs captured monsoon rainfall and regulated its release through a network of canals and sluice gates, enabling rice farmers to cultivate three harvests per year instead of the single harvest that rain-fed agriculture allowed. Historian Priya Narasimhan argues that this capacity for surplus grain production was the economic engine that funded Angkor''s monumental temple-building program, including the construction of Angkor Wat in the early twelfth century.', $lyceon_json$[{"key":"A","text":"To supply water for the construction of monumental temples such as Angkor Wat"},{"key":"B","text":"To capture and regulate monsoon rainfall so that rice farmers could produce multiple annual harvests"},{"key":"C","text":"To prevent catastrophic flooding in the low-lying areas surrounding Angkor"},{"key":"D","text":"To demonstrate the technological superiority of the Khmer Empire over neighboring kingdoms"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that the barays captured monsoon rainfall and regulated its release to enable three rice harvests per year instead of one. The option about supplying water for temple construction conflates the economic surplus that funded temples with the direct purpose of the reservoirs. The option about preventing catastrophic flooding introduces a function never mentioned in the passage. The option about demonstrating technological superiority attributes a motive that the text does not support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SEWUO4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Tomoko Ishikawa has studied obsidian artifacts recovered from Neolithic sites on the Japanese island of Hachijojima, located roughly 290 kilometers south of Tokyo in the open Pacific. Chemical analysis using X-ray fluorescence spectroscopy revealed that the obsidian did not originate from Hachijojima''s own volcanic deposits but matched the geochemical signature of obsidian quarries on Kozushima, an island 150 kilometers to the northwest. The artifacts date to approximately 30,000 years before present—a period when sea levels were lower than today but Kozushima was still separated from Hachijojima by at least 50 kilometers of open ocean with no intervening islands. Ishikawa notes that the obsidian blades show standardized knapping patterns inconsistent with occasional, accidental acquisition. Her findings therefore suggest that ________', $lyceon_json$[{"key":"A","text":"Neolithic populations in the region engaged in deliberate, repeated open-ocean voyaging far earlier than most models of early maritime capability have assumed."},{"key":"B","text":"the obsidian deposits on Hachijojima were exhausted by intensive quarrying long before the artifacts in question were produced."},{"key":"C","text":"Kozushima's volcanic activity during the Neolithic period was significantly more intense than geologists had previously estimated."},{"key":"D","text":"the standardized knapping patterns found on the artifacts were developed independently by separate populations on different islands."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that obsidian on Hachijojima came from Kozushima across at least 50 kilometers of open ocean, the artifacts are 30,000 years old, and the knapping patterns indicate systematic rather than accidental acquisition. The logical inference is that deliberate, repeated open-ocean voyaging occurred far earlier than conventionally assumed. The option about exhausted local obsidian deposits contradicts the passage, which states the obsidian did not match Hachijojima''s own volcanic deposits—implying a different geochemical signature, not depletion. The option about more intense volcanic activity on Kozushima is irrelevant to how the obsidian traveled 150 kilometers across open water. The option about independent development of knapping patterns contradicts the passage''s point that standardized patterns indicate systematic transport from a single source, not parallel invention.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SM1PW3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Historian Marcus Fell contends that the construction of transcontinental railroads in the 1860s was the single most important factor in the economic development of the American West, arguing that railroads created markets where none had previously existed and attracted settlers who transformed the region''s economy within a single generation.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U6YZX3', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article for a history journal and wants to challenge the conventional view that the Pony Express was a commercial success. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WCYKJS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Linguist Helena Sørensen has documented over thirty endangered tonal languages in Southeast Asia, cataloging pitch patterns that encode grammatical distinctions absent from most Indo-European _____ her fieldwork has occasionally required her to develop entirely new transcription symbols to represent sounds that existing phonetic alphabets cannot capture.', $lyceon_json$[{"key":"A","text":"languages; moreover,"},{"key":"B","text":"languages, moreover,"},{"key":"C","text":"languages; instead,"},{"key":"D","text":"languages, she"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank separates two independent clauses: one about Sørensen''s documentation of tonal languages and their grammatical distinctions, and another about her development of new transcription symbols. A semicolon correctly joins these independent clauses, and the conjunctive adverb "moreover" accurately signals that the second clause adds further notable information about her fieldwork. Using a comma before the conjunctive adverb "moreover" creates a comma splice, which is a boundary error. Using "instead" after the semicolon mischaracterizes the relationship between the clauses; the second clause does not present an alternative to the first but rather provides additional information. Using a comma followed by "she" creates a comma splice by joining two independent clauses with only a comma and no coordinating conjunction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WD7FKI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 1930s, photographer Dorothea Lange documented the struggles of migrant farmworkers in California''s Central Valley. Her most famous image, Migrant Mother, became an enduring symbol of the Great _____ the photograph''s emotional power transcended its documentary origins and influenced generations of photojournalists.', $lyceon_json$[{"key":"A","text":"Depression, and"},{"key":"B","text":"Depression"},{"key":"C","text":"Depression, so"},{"key":"D","text":"Depression, however,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses with an additive relationship are joined here. A comma followed by the coordinating conjunction ''and'' correctly links them, signaling that the second clause adds information to the first. Omitting all punctuation creates a run-on sentence, a sentence boundary error. Using the coordinating conjunction ''so'' implies a cause-and-effect relationship, but the second clause does not follow as a consequence of the first — it adds parallel information, making ''so'' a rhetorical purpose error. Using ''however'' after a comma creates a comma splice, since ''however'' is a conjunctive adverb requiring a semicolon or period before it, and it signals contrast rather than addition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WWKXJX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of geochemists at the University of Bergen has analyzed sediment cores from the floor of the Norwegian Sea. The research, which involved drilling at eleven sites along the mid-ocean ridge over a span of fourteen months, _____ that volcanic activity beneath the seafloor was substantially more intense during the late Paleocene than previously estimated.', $lyceon_json$[{"key":"A","text":"indicates"},{"key":"B","text":"indicate"},{"key":"C","text":"have indicated"},{"key":"D","text":"indicating"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the verb is "research," a singular uncountable noun. The long relative clause "which involved drilling at eleven sites along the mid-ocean ridge over a span of fourteen months" is set off by commas and modifies "research" but does not change its number. The plural nouns within the intervening clause — "sites" and "months" — may tempt a reader to select a plural verb, but none of these is the subject. The singular present-tense verb "indicates" correctly agrees with "research." The bare plural "indicate" does not agree with the singular subject. The plural present-perfect "have indicated" fails on number agreement. The present participle "indicating" is not a finite verb and would leave the sentence without a main predicate, creating a fragment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X8KBLG', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the nineteenth-century geologist Charles Lyell initially ______ the idea that volcanic activity could reshape entire coastlines within a single human lifetime, his subsequent fieldwork along the Campanian shore in 1828 forced him to revise this skepticism dramatically.', $lyceon_json$[{"key":"A","text":"dismissed"},{"key":"B","text":"celebrated"},{"key":"C","text":"fabricated"},{"key":"D","text":"memorized"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Lyell held skepticism toward the idea, which he later revised. A word meaning rejected or disregarded aligns with that initial skepticism. The option meaning praised or honored contradicts the skepticism described. The option meaning invented or made up implies Lyell originated the idea rather than responded to it, which conflicts with the passage''s framing. The option meaning committed to memory describes a cognitive process unrelated to the evaluative stance the passage describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YVVDJV', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on renewable energy storage and wants to present a contrast between the two battery technologies described in the notes. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
